const PROCESS_ART={"kaavadDevelopment":"data:image/webp;base64,","heeraIdentity":"data:image/webp;base64,","heeraDieline":"data:image/webp;base64,","heeraFinal":"data:image/webp;base64,","sparkyAssets":"data:image/webp;base64,","sparkyFlow":"data:image/webp;base64,","sparkyThumbnail":"data:image/webp;base64,","heeraThumbnail":"data:image/webp;base64,","monsterThumbnail":"data:image/webp;base64,"};
const processAssetRoot=document.currentScript?.src.includes('cdn.websitepublisher.ai')?'/assets/':'assets/';
const pageEvidence=(id,i)=>typeof ZINE_PAGES!=='undefined'?ZINE_PAGES[id][i]:`assets/${id}-pages/${i}.jpg`;
if(!projects.some(p=>p.id==='monster'))projects.push({id:'monster',name:'Monster F1 Limited Edition',tag:'Packaging concept',text:'An F1-inspired limited-edition Monster Energy packaging design.',link:'https://www.behance.net/gallery/247543789/Monster-F1-Limited-Edition-Packaging'});
const caseStudies={
 privacy:{brief:'Make phone-level permission choices easier to understand, remember and change.',role:'Research and UI/UX concept development; connected mobile interface and browser prototype.',scope:'Concept project · 40 navigable prototype states',steps:[['Understand the decision','The research presentation frames the journey as before, during and after consent: why access is needed, what is accessed, how long it lasts and how someone can withdraw it.'],['Explore the interface','The documented visual directions included a system-led approach, bold alerts and a calmer trust-led direction. The current prototype uses graphite, warm white and green, with progressively disclosed explanations.'],['Refine the flow','Critique identified crowding, repeated headings and inconsistent alignment. The development notes call for simpler wireframes and checks across wording, scrolling and state consistency.']],decision:'Scope, duration and declared handling are separated so the permission choice can be understood in smaller parts. Receipts and the control centre give a route back after consent.',outcome:'An interactive browser prototype with 40 navigable states. Interface counts and dates are sample data; interaction and usability validation remain development work.',figures:'privacy'},
 sparky:{brief:'Explore how a packaging-linked AR game can make a brushing routine more engaging for children.',role:'AR experience concept and interaction development, character-led visual presentation and Lens build.',scope:'Augmented reality · Packaging marker · Interactive demo',steps:[['Build the concept','The presentation describes a three-step adventure: scan the packaging, reveal Sparky in AR, then tap germs.'],['Assemble the world','The asset breakdown brings together the hero model, four coloured germ characters, the packaging marker, the palette and audio cues.'],['Connect action and feedback','The build pairs the package-triggered reveal with tap interactions and germ-pop effects. The final recording shows the experience in use.']],decision:'The sequence introduces one action at a time: recognise the pack, meet the character and interact with the germs.',outcome:'A recorded packaging-linked AR experience. The project explores engagement; it does not establish a measured change in brushing habits.',figures:'sparky'},
 kaavad:{brief:'Translate the traditional Kaavad storytelling craft into an illustrated editorial publication.',role:'Publication design, illustration, visual system and spread development.',scope:'Editorial publication · 40 pages',steps:[['Set the visual language','The supplied process board identifies warm beige, deep earth green, muted sage, terracotta red and mustard yellow as the publication palette.'],['Plan the spreads','The wireframe sheet maps text blocks, illustration placement, cultural motifs and image-led pages before the final reading experience.'],['Resolve the publication','The final pages combine framed illustrations, recurring borders and typographic hierarchy. The flipbook above presents the finished publication.']],decision:'A repeated border and restrained colour family connect changing stories and illustrations across the book.',outcome:'A 40-page illustrated publication, with its own front cover, paired interior pages and back cover.',figures:'kaavad'},
 arrival:{brief:'Present a speculative world through an editorial archive of alerts, environments and survival information.',role:'Editorial composition, visual storytelling and publication design.',scope:'Speculative editorial · 20 pages',steps:[['Establish the world','The finished pages use dark cityscapes, warning language and archive-like numbering to introduce the speculative setting.'],['Build a visual rhythm','The selected excerpts show the relationship between large environmental images, compact labels and typographic information. These are final-work details, not early drafts.'],['Read as a publication','The 20-page sequence is presented in the flipbook, with covers separated from the interior spreads.']],decision:'The contrast between atmospheric imagery and restrained technical labels gives the publication the character of an unfolding archive.',outcome:'A 20-page editorial publication. The excerpts below describe its final visual system; original sketch-stage material was not included in the supplied files.',figures:'arrival'},
 wastu:{brief:'Develop website and visual communication work for an architectural visualisation company.',role:'Visual Designer and Design Program Manager Intern; website layouts, client feedback and coordination of two design interns.',scope:'WastuViz · Internship · May - September 2026',steps:[['Work from the brief','The internship involved coordinating client briefs, feedback and delivery alongside visual design work.'],['Develop the digital presentation','Website layouts formed part of a broader set of assets across print, digital, email and web. The image here is a supplied WastuViz visual, rather than a historical wireframe.'],['Refine through feedback','Layouts were refined through client feedback and implementation work. The project link opens the current WastuViz website.']],decision:'Keep the visual work and the company’s immersive architectural offering connected across website and communication formats.',outcome:'Website and visual communication contributions during the internship. The current company website may include work by the wider team.',figures:'wastu'},
 pack:{brief:'Revisit Heera Sweets’ identity and Jamun Chips packaging as a branding and packaging redesign study.',role:'Identity exploration, packaging graphics, carton and sleeve design.',scope:'Heera Sweets · Packaging redesign concept',steps:[['Review the starting point','The source presentation shows the original logo and packaging before the proposed redesign.'],['Develop the identity','The annotated mark explores Devanagari letterforms, a diamond symbol and a bindi detail, supported by an olive, plum and gold visual palette.'],['Apply it to the package','The artwork develops a primary-carton dieline and an outer wraparound sleeve, followed by dimensional packaging mockups.']],decision:'The redesigned mark and botanical line artwork form a shared system across the carton, sleeve and mockup views.',outcome:'A proposed identity and packaging system shown through flat artwork and mockups; this is a redesign study rather than a claim of a commissioned brand launch.',figures:'pack'}
};
function caseFigure(src,alt,caption){return `<figure class="case-figure"><img src="${src}" alt="${alt}" loading="lazy"><figcaption>${caption}</figcaption></figure>`}
function caseVisuals(kind){
 if(kind==='privacy')return '<div class="consent-map"><div><small>BEFORE</small><b>Understand the request</b><p>Purpose, scope and useful context.</p></div><div><small>DURING</small><b>Make a bounded choice</b><p>Approximate or precise. Once or while using.</p></div><div><small>AFTER</small><b>Review and change</b><p>Consent receipt, expiry and access controls.</p></div></div><div class="case-direction"><span><i style="background:#242522"></i>Graphite</span><span><i style="background:#f5f4f0"></i>Warm white</span><span><i style="background:#355d49"></i>Green</span></div>';
 if(kind==='sparky')return caseFigure(PROCESS_ART.sparkyFlow,'Scan packaging, reveal Sparky, tap germs','Concept sequence from the supplied Sparky presentation.')+caseFigure(PROCESS_ART.sparkyAssets,'Sparky hero, germ characters, marker, palette and sound cues','Asset breakdown from the supplied process presentation.');
 if(kind==='kaavad')return caseFigure(PROCESS_ART.kaavadDevelopment,'Kaavad palette and spread wireframes','Palette and layout planning from the Kaavad process board.')+`<div class="case-pair">${caseFigure(pageEvidence('kaavad',3),'Kaavad final editorial page','Final page detail.')}${caseFigure(pageEvidence('kaavad',4),'Kaavad final illustrated page','Final illustration and framing.')}</div>`;
 if(kind==='arrival')return `<div class="case-pair">${caseFigure(pageEvidence('arrival',3),'Arrival final page detail','Final-work excerpt: atmosphere and imagery.')}${caseFigure(pageEvidence('arrival',4),'Arrival archive-style page','Final-work excerpt: labels, numbering and hierarchy.')}</div>`;
 if(kind==='wastu')return caseFigure(processAssetRoot+'wastu-preview.webp','Supplied WastuViz architectural visual','Supplied project visual. Open the current company website above for the live experience.');
 return caseFigure(PROCESS_ART.heeraIdentity,'Heera original branding and annotated proposed logo','Starting identity and the proposed logo rationale from the source artwork.')+caseFigure(PROCESS_ART.heeraDieline,'Heera carton and outer-sleeve artwork','Flat packaging development from the source Illustrator document.');
}
const openBeforeCaseStudy=openProject;
openProject=function(id){
 openBeforeCaseStudy(id);const item=caseStudies[id];if(!item)return;const body=document.querySelector('#modalbody');if(body.querySelector('.case-study'))return;
 const heroLabel=document.createElement('p');heroLabel.className='case-final-label';heroLabel.textContent='THE FINAL WORK';const media=body.querySelector('.book,video,iframe');if(media)media.before(heroLabel);
 if(id==='pack'){const image=document.createElement('img');image.className='case-final-art';image.src=PROCESS_ART.heeraFinal;image.alt='Heera Sweets final packaging mockups';body.querySelector('p:nth-of-type(2)')?.after(image);}
 const content=document.createElement('section');content.className='case-study';content.innerHTML=`<p class="eyebrow">INSIDE THE PROJECT</p><h2>From idea<br>to outcome.</h2><p class="case-scope">${item.scope}</p><div class="case-overview"><div><h3>The brief</h3><p>${item.brief}</p></div><div><h3>My role</h3><p>${item.role}</p></div></div><div class="case-steps">${item.steps.map((s,i)=>`<article><span>0${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div></article>`).join('')}</div><div class="case-evidence">${caseVisuals(item.figures)}</div><details class="case-decision"><summary>What shaped the decisions?<span>+</span></summary><p>${item.decision}</p></details><div class="case-outcome"><small>THE OUTCOME</small><p>${item.outcome}</p></div><button class="case-top" type="button">Back to the final work ↑</button>`;body.append(content);
 content.querySelector('.case-top').onclick=()=>document.querySelector('#modal').scrollTo({top:0,behavior:'smooth'});
 content.querySelectorAll('.case-steps article,.case-figure,.case-outcome').forEach(el=>{el.classList.add('scroll-reveal');revealObserver.observe(el)});replaceArrowIcons(content);
};
// Ambient motion runs without hover or scroll, and pauses outside the viewport.
const ambientObserver=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('ambient-active',entry.isIntersecting)),{threshold:.08});
function addAmbientPreviewMotion(){
 document.querySelectorAll('.ref-hero,.door-frame,.ref-contact,.room-project').forEach(el=>{if(!el.dataset.ambientReady){el.dataset.ambientReady='true';ambientObserver.observe(el)}});
 const phone=document.querySelector('.privacy-thumb .mini-phone');if(phone&&!phone.querySelector('.preview-receipt')){const note=document.createElement('div');note.className='preview-receipt';note.textContent='Approximate location · Access recorded';phone.append(note);}
 document.querySelectorAll('.room-project[data-room-project="arrival"],.room-project[data-room-project="kaavad"]').forEach(card=>{const box=card.firstElementChild;if(box.querySelector('.preview-paper'))return;const id=card.dataset.roomProject;box.classList.add('zine-ambient');const leaf=document.createElement('img');leaf.className='preview-paper';leaf.src=pageEvidence(id,1);leaf.alt='Interior page preview';box.append(leaf);});
 const packaging=document.querySelector('.room-project[data-room-project="pack"]');if(packaging&&!packaging.dataset.realArtwork){packaging.dataset.realArtwork='true';packaging.firstElementChild.innerHTML=`<img class="heera-real-preview" src="${PROCESS_ART.heeraThumbnail}" alt="Heera Sweets packaging mockup">`;}
}
addAmbientPreviewMotion();new MutationObserver(addAmbientPreviewMotion).observe(document.querySelector('.room-content'),{childList:true,subtree:true});

function refreshSelectedThumbnails(){
 document.querySelectorAll('.room-project[data-room-project="sparky"],.room-project[data-room-project="pack"],.room-project[data-room-project="monster"]').forEach(card=>{if(card.dataset.thumbnailUpdated)return;card.dataset.thumbnailUpdated='true';const id=card.dataset.roomProject;const artwork=id==='sparky'?PROCESS_ART.sparkyThumbnail:id==='pack'?PROCESS_ART.heeraThumbnail:PROCESS_ART.monsterThumbnail;const art=card.firstElementChild;art.classList.add('artwork-thumbnail','artwork-'+id);art.innerHTML=`<img src="${artwork}" alt="${id==='sparky'?'Sparky Germ Busters AR experience':id==='pack'?'Heera Sweets Jamun Chips packaging':'Monster F1 limited-edition packaging artwork'}"><span class="artwork-badge">${id==='sparky'?'AR EXPERIENCE':id==='pack'?'PACKAGING REDESIGN':'VIEW ON BEHANCE'}</span>`;if(id==='monster'){card.onclick=()=>window.open('https://www.behance.net/gallery/247543789/Monster-F1-Limited-Edition-Packaging','_blank','noopener');card.setAttribute('aria-label','View Monster F1 Limited Edition packaging on Behance');}});
}
new MutationObserver(refreshSelectedThumbnails).observe(document.querySelector('.room-content'),{childList:true,subtree:true});refreshSelectedThumbnails();
